<?php namespace App\Http\Controllers; use App\Models\WelcomeSlide; use Illuminate\Http\Request; class WelcomeSlideController extends Controller { private function rules():array{return ['title'=>'required|max:255','subtitle'=>'nullable|max:255','image_path'=>'required|max:255','button_label'=>'nullable|max:100','button_url'=>'nullable|max:255','sort_order'=>'nullable|integer','is_active'=>'nullable|boolean'];} public function index(){return view('console.welcome-slides',['slides'=>WelcomeSlide::orderBy('sort_order')->get()]);} public function store(Request $request){$data=$request->validate($this->rules());$data['is_active']=$request->boolean('is_active');WelcomeSlide::create($data);return back()->with('success','Slide ditambahkan.');} public function update(Request $request,WelcomeSlide $slide){$data=$request->validate($this->rules());$data['is_active']=$request->boolean('is_active');$slide->update($data);return back()->with('success','Slide diperbarui.');} public function destroy(WelcomeSlide $slide){$slide->delete();return back()->with('success','Slide dihapus.');} }
